class Solution {
    public double myPow(double x, int n) {
        var result = helper(x, Math.abs(n));
        return n >= 0 ? result : 1 / result;
    }

    double helper(double x, int n) {
        if (n == 0) {
            return 1;
        }

        if (n == 1) {
            return x;
        }

        var half = helper(x, n / 2);
        if (n % 2 == 0) {
            return half * half;
        } else {
            return half * half * x;
        }
    }
}

