class Solution {
public:
    double myPow(double x, int n) {
        if (n == 0) {
            return 1;
        } else if (n == 1) {
            return x;
        } else if (n == -1) {
            return 1 / x;
        } else {
            double half = myPow(x, n / 2);
            double left = (n % 2 == 0) ? 1: x;
            if (n > 0) {
                return half * half * left;
            } else {
                return half * half / left;
            }
        }
    }
};

